void test_stream_done_signal(void) {
    /* Verify that the [DONE] sentinel signal properly terminates the stream */
    LITERLLMAlefHandle chat_completion_request_handle = literllm_chat_completion_request_from_json("{\"messages\":[{\"content\":\"Say done\",\"role\":\"user\"}],\"model\":\"gpt-4\",\"stream\":true}");
    assert(chat_completion_request_handle != 0 && "failed to build request");
    const char* mock_base = getenv("MOCK_SERVER_URL");
    assert(mock_base != NULL && "MOCK_SERVER_URL must be set");
    char base_url[1024];
    snprintf(base_url, sizeof(base_url), "%s/fixtures/stream_done_signal", mock_base);
    LITERLLMAlefHandle client = literllm_create_client("test-key", base_url, (uint64_t)-1, (uint32_t)-1, NULL);
    assert(client != 0 && "failed to create client");
    LITERLLMAlefHandle stream_handle = literllm_default_client_chat_stream_start(client, chat_completion_request_handle);
    assert(stream_handle != 0 && "expected stream-start to succeed");
    size_t chunks_count = 0;
    char* stream_content = (char*)malloc(1);
    assert(stream_content != NULL);
    stream_content[0] = '\0';
    size_t stream_content_len = 0;
    int no_chunks_after_done = 1; /* true by construction: the loop below cannot call stream_next again once it observes done */
    char *stream_finish_reason = NULL;

    while (1) {
        LITERLLMAlefHandle result = literllm_default_client_chat_stream_next(stream_handle);
        if (result == 0) {
            assert(literllm_last_error_code() == 0 && "the stream ended with an error");
            break;
        }
        chunks_count++;
        char *chunk_choices = literllm_chat_completion_chunk_choices(result);
        if (chunk_choices != NULL) {
            char *first_choice_json = alef_json_array_get_index(chunk_choices, 0);
            if (first_choice_json != NULL) {                char *choice_finish = alef_json_get_string(first_choice_json, "finish_reason");
                if (choice_finish != NULL && strcmp(choice_finish, "null") != 0) {
                    free(stream_finish_reason);
                    stream_finish_reason = choice_finish;
                } else {
                    free(choice_finish);
                }                LITERLLMAlefHandle first_choice = literllm_stream_choice_from_json(first_choice_json);
                if (first_choice != 0) {
                    LITERLLMAlefHandle delta = literllm_stream_choice_delta(first_choice);
                    if (delta != 0) {
                        char *delta_content = literllm_stream_delta_content(delta);
                        if (delta_content != NULL) {
                            size_t delta_len = strlen(delta_content);
                            char *grown = (char *)realloc(stream_content, stream_content_len + delta_len + 1);
                            assert(grown != NULL);
                            stream_content = grown;
                            memcpy(stream_content + stream_content_len, delta_content, delta_len + 1);
                            stream_content_len += delta_len;
                            literllm_free_string(delta_content);
                        }
                        literllm_stream_delta_free(delta);
                    }
                    literllm_stream_choice_free(first_choice);
                }                free(first_choice_json);
            }
            literllm_free_string(chunk_choices);
        }
        literllm_chat_completion_chunk_free(result);
    }
    literllm_default_client_chat_stream_free(stream_handle);

    assert((stream_finish_reason != NULL) && "is_true assertion failed for stream_complete");
    assert((strcmp(stream_content, "Done") == 0) && "equals assertion failed for stream_content");
    assert(no_chunks_after_done && "expected no_chunks_after_done to be true");
    free(stream_content);
    free(stream_finish_reason);
    literllm_chat_completion_request_free(chat_completion_request_handle);
    literllm_default_client_free(client);
    /* suppress unused */ (void)no_chunks_after_done; (void)chunks_count; (void)stream_content_len;
}

